import{_ as n,l as i,o as e,c as o,v as t,p as s,x as r,d as l,i as B,S as C}from"./chunks/framework.InCnrqk-.js";const m=JSON.parse('{"title":"主权 CDS","description":"","frontmatter":{"title":"主权 CDS","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/sovereign-cds.md","filePath":"quant/sovereign-cds.md","lastUpdated":1789023840000}'),A={name:"quant/sovereign-cds.md"};function d(D,a,p,h,c,S){const E=i("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="主权-cds" tabindex="-1">主权 CDS <a class="header-anchor" href="#主权-cds" aria-label="Permalink to &quot;主权 CDS&quot;">​</a></h1><div class="epigraph"><p>主权信用事件写在 ISDA 定义里：支付失败、重组、拒绝偿付与延期，并不自动等于「国家破产」。希腊式的集体行动条款与本币重组，曾让市场争论保护到底有没有被触发。</p><footer>—— 对照 Duffie 的 CDS 估值框架与 ISDA 主权信用事件定义；希腊 2012 年重组是关键样本</footer></div><p>主权 CDS 在合约形式上与公司 CDS 同族：保护腿对信用事件支付，费用腿支付升水，见 <a href="/quant/cds-pricing">CDS 定价</a>。经济对象却不同。主权没有 Merton 意义上的股权清算，本币债可以通过通胀、重组或法律变更减记；外部法美元债与本币债不是同一回收。货币、quanto、CACs、重组是否构成信用事件，决定保护的真实边界。阿根廷、希腊、乌克兰、厄瓜多尔等案例反复说明：升水曲线可以很有流动性，事件认定却是法律与政治过程。本篇写主权 CDS 的合约与quanto、与本币债基差，以及它为何不能当成「国家违约概率」的直读。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>公司 CDS 的参考实体有相对清晰的破产程序与可交割公司债。主权的「违约」经常是重组谈判：延长期限、削减票息、本金发新债换旧债。ISDA 定义下的重组信用事件要求满足特定门槛与约束；集体行动条款（CAC）迫使未参与的持有人也进入重组时，是否触发 CDS，取决于定义版本与认定委员会。2012 年希腊：集体行动迫使减记，CDS 最终被认定触发，但过程本身造成了「保护是否存在」的基差波动。此后欧洲主权合同与 CAC 设计部分吸收了这次经验，并不能保证下一国复制同一路径。</p><p>第二个问题是货币。欧元区主权的美元 CDS 与欧元 CDS 可以差一截：quanto 反映的是「违约时欧元相对美元的跳跃」以及两套合约的流动性。本币升水再低，也不等于外部法债券安全。用本币债利差去减美元 CDS 得到的「基差」，混了货币、管辖与可交割集合，见 <a href="/quant/cds-bond-basis">CDS–债券基差</a>。</p><h3 id="没有股权缓冲时回收意味着什么" tabindex="-1">没有股权缓冲时回收意味着什么 <a class="header-anchor" href="#没有股权缓冲时回收意味着什么" aria-label="Permalink to &quot;没有股权缓冲时回收意味着什么&quot;">​</a></h3><p>结构模型里股权先被打到零再轮到债。主权的「股权」是征税权与政治意愿，不能在交易所清算。回收取决于谈判、IMF 计划、国内银行是否被同时重组、以及可交割债是外部法还是本币。标准 40% 回收对主权尤其只是惯例：历史重组的净现值减记可以从很低到很高，见 <a href="/quant/recovery-assumption">回收率假设</a>。把主权升水用 \\(s\\approx(1-R)\\lambda\\) 读成违约概率，会把重组频率与减记深度搅在同一个数里。</p><p><span class="marginnote">认定委员会的决定是离散事件。在决议前，CDS 盯市会剧烈波动，即使「经济上已经重组」。模型若假设信用事件与损失同时、确定发生，会错过这段法律基差。交易限额应单独管理认定窗口。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>定价引擎仍是强度自举：主权 CDS 曲线给出风险中性的事件强度（在合约定义下），不是统计局的债务危机频率。应分开标定美元与本币（或欧元）曲线，quanto 用交叉货币基差与隐含货币跳跃来解释，而不是强制两条曲线相等。可交割义务清单、重组条款版本、是否包含政府干预或延期，必须写入曲线标识；同一主权的旧定义与新定义可以并存一段时间。</p><p>对冲上，主权 CDS 常被用来对冲银行账簿里的主权债与国家风险转移。银行体系与主权是错向的：主权事件发生时，国内银行保护卖方与抵押品同时恶化，CVA 与错误方向风险比公司名字更极端，见 <a href="/quant/counterparty-credit">对手方信用</a>。用指数（如 SovX）对冲单国，构成与滚动问题与 <a href="/quant/cdx-vs-single">公司指数</a> 类似，但国家权重和政治事件更集中。</p><p>压力应包含：重组触发但回收极高（「温和重组」）、触发且回收极低、以及不触发但债券 NPV 已大幅受损（基差爆炸）。第三种情景是主权 CDS 作为对冲最危险的缺口——信用事件定义比经济损失窄。</p><h3 id="本币债、外部债与-cac" tabindex="-1">本币债、外部债与 CAC <a class="header-anchor" href="#本币债、外部债与-cac" aria-label="Permalink to &quot;本币债、外部债与 CAC&quot;">​</a></h3><p>外部法债券（纽约法、英国法）更常进入 CDS 可交割篮子。本币债可能被国内立法直接减记而不满足旧定义下的重组。新一代 CAC 与合同改革试图减少「选择性违约」：只重组一部分工具、让 CDS 落空。分析一个国家的保护是否有效，应读当前 ISDA 定义与该国债券契约，而不是读五年升水的水平。评级迁移对主权样本极稀，矩阵的违约列不可靠，更应把 CDS 与债券价格当主市场，把评级当滞后的离散标签，见 <a href="/quant/rating-migration">评级迁移</a>。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>主权升水补偿的是合约定义下的或有支付，外加流动性与经销商资本。风险溢价可以很大：即使事件概率低，事件发生时的宏观状态极差（全球风险厌恶、本国银行体系），持有保护或持有债券的风险溢价都不等于精算概率。Duffie 的强度框架仍然适用，但强度对应的是「认定委员会会宣布事件」，边际上被法律技术推动。</p><p>Quanto 机制：若违约时本国货币贬值，欧元保护的损失以弱货币计，美元保护更值钱，美元升水应更高。金融危机里这个跳跃相关可以突然升高，两条曲线的差不是噪声。外汇对冲过的本币债与未对冲的 CDS 不能直接比较 CS01。</p><p><span class="marginnote">国内银行大量持有本国主权债时，主权 CDS 的净空头可能集中在少数国际经销商。流动性在最需要时消失，升水曲线的中价不能执行。这是市场微观结构，不是强度模型的参数失效。</span></p><h3 id="与公司名字的错向与传导" tabindex="-1">与公司名字的错向与传导 <a class="header-anchor" href="#与公司名字的错向与传导" aria-label="Permalink to &quot;与公司名字的错向与传导&quot;">​</a></h3><p>主权压力通过银行、担保与国有企业传导到公司 CDS。用主权保护去对冲「该国所有信用」会留下企业特异与银行次级。反过来，只对冲公司账簿而不管主权曲线，会在重组年出现共同因子缺口。宏观信用组合应把主权曲线当成显式因子，而不是把所有名字的 \\(\\lambda\\) 相关用一个高斯 \\(\\rho\\) 概括。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要把主权 CDS 升水翻译成「该国明年破产的概率」。不要用本币政策利率去贴现美元保护。不要假设重组一定触发、一定按 40% 结算。不要忽略净结算与拍卖：可交割主权债的存量、是否被锁在国内账户，会影响拍卖价格。新兴市场还有外汇管制、暂停交易与强制转换，路径依赖超出标准强度模型。</p><p>研究时间序列时，合约定义变更必须切样本。欧盟、ISDA 与各国 CAC 改革会改变同一「五年升水」的经济含义。工程上，主权曲线应与外汇远期、交叉货币基差、债券可交割清单一起版本化；风险报告要有「事件认定」情景，而不仅是平行升水移动。</p><p><span class="marginnote">持有本国主权债的银行用本国主权 CDS 对冲，在系统危机里可能面临保护卖方与参考实体同时出问题，以及监管对净空头主权 CDS 的限制。对冲比率在压力里不可行，应在限额里预先扣减。</span></p>',25)),(e(),s(C,null,{default:r(()=>[B(E,{id:"mermaid-73",class:"mermaid",graph:"flowchart%20TD%0A%20%20DEF%5B%22ISDA%20%E4%B8%BB%E6%9D%83%E4%BF%A1%E7%94%A8%E4%BA%8B%E4%BB%B6%E5%AE%9A%E4%B9%89%22%5D%20--%3E%20EVT%5B%22%E6%94%AF%E4%BB%98%E5%A4%B1%E8%B4%A5%20%2F%20%E9%87%8D%E7%BB%84%20%2F%20%E6%8B%92%E7%BB%9D%20%2F%20%E5%BB%B6%E6%9C%9F%22%5D%0A%20%20CAC%5B%22CACs%20%E4%B8%8E%E6%9C%AC%E5%B8%81%E7%AB%8B%E6%B3%95%22%5D%20--%3E%20EVT%0A%20%20EVT%20--%3E%20TRIG%5B%22%E8%AE%A4%E5%AE%9A%E5%A7%94%E5%91%98%E4%BC%9A%3A%20%E6%98%AF%E5%90%A6%E8%A7%A6%E5%8F%91%22%5D%0A%20%20CURVE%5B%22%E7%BE%8E%E5%85%83%20%2F%20%E6%9C%AC%E5%B8%81%20CDS%20%E6%9B%B2%E7%BA%BF%22%5D%20--%3E%20LAM%5B%22%E5%BC%BA%E5%BA%A6%E8%87%AA%E4%B8%BE%22%5D%0A%20%20QTO%5B%22Quanto%20%2F%20%E8%B4%A7%E5%B8%81%E8%B7%B3%E8%B7%83%22%5D%20--%3E%20CURVE%0A%20%20TRIG%20--%3E%20PAY%5B%22%E6%8B%8D%E5%8D%96%E5%9B%9E%E6%94%B6%E4%B8%8E%E7%BB%93%E7%AE%97%22%5D%0A%20%20LAM%20--%3E%20HEDGE%5B%22%E5%AF%B9%E5%86%B2%E4%B8%BB%E6%9D%83%E5%80%BA%E4%B8%8E%E5%9B%BD%E5%AE%B6%E9%A3%8E%E9%99%A9%22%5D%0A%20%20HEDGE%20--%3E%20WW%5B%22%E9%93%B6%E8%A1%8C-%E4%B8%BB%E6%9D%83%E9%94%99%E5%90%91%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>主权 CDS 用与公司相同的强度定价外壳，但信用事件是法律定义下的重组与支付失败，不是企业破产。</li><li>希腊 2012 说明 CAC 与认定过程本身会成为基差与对冲缺口的来源。</li><li>美元与本币曲线之差含 quanto 与管辖；回收惯例对主权更不可靠。</li><li>对冲必须处理银行–主权错向、可交割性与「经济损失但不触发」的情景。</li><li>出处：Duffie, <em>Credit Swap Valuation</em>, 1999；Duffie and Singleton, <em>Credit Risk</em>, 2003；ISDA 信用事件定义与认定委员会实践；希腊重组与 CDS 触发是主权合约的关键案例。</li></ul>',2))])}const f=n(A,[["render",d]]);export{m as __pageData,f as default};
